<?php
require_once __DIR__.'/app/lib/Db.php';require_once __DIR__.'/app/lib/Security.php';require_once __DIR__.'/app/lib/Entitlements.php';require_once __DIR__.'/app/lib/ProjectDecisionMatrix.php';$pdo=Db::pdo();Security::start();$u=Security::user();if(!$u){header('Location: /login?next='.rawurlencode('/decision-matrix'));exit;}Entitlements::requireFeature($pdo,$u,'basic_decision_matrix');$ctx=Entitlements::context($pdo,$u);$csrf=Security::csrf();$pro=!empty($ctx['features']['weighted_decision_matrix']);$weights=ProjectDecisionMatrix::defaultWeights();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Decision Matrix | TechSelectAI</title><style>body{font-family:Inter,Arial,sans-serif;background:#f6f8fb;color:#14213d;margin:0}main{max-width:1200px;margin:auto;padding:24px}.card{background:#fff;border:1px solid #e4e9f0;border-radius:14px;padding:16px;margin-bottom:16px}.row{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}input,select{width:100%;box-sizing:border-box;padding:9px;border:1px solid #cbd5e1;border-radius:8px}button{border:0;border-radius:8px;padding:9px 12px;background:#1d4ed8;color:#fff;cursor:pointer}.secondary{background:#475569}.badge{display:inline-block;padding:3px 7px;border-radius:999px;background:#eef2ff;font-size:11px}.muted{color:#64748b}.product{border:1px solid #e5e7eb;border-radius:12px;padding:14px;margin:10px 0}.score{font-size:28px;font-weight:800}.dims{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;font-size:12px}.warning{background:#fff7ed;padding:8px;border-radius:8px}.ok{background:#ecfdf5;padding:8px;border-radius:8px}.provider-link{display:inline-flex;margin-top:8px;padding:8px 10px;border:1px solid #bfdbfe;border-radius:8px;text-decoration:none;font-weight:700;color:#1d4ed8;background:#eff6ff}@media(max-width:800px){.row,.dims{grid-template-columns:1fr 1fr}}</style></head><body><main><h1>Contextual Decision Matrix</h1><p class="muted">Project-specific fit is calculated from your saved requirements. It does not replace the public TechSelectAI evaluation score.</p><div class="card"><div class="row"><div><label>Selection project ID</label><input id="pid" type="number" value="<?=htmlspecialchars($_GET['project_id']??'')?>"></div><?php foreach($weights as $k=>$v): ?><div><label><?=htmlspecialchars(ucwords(str_replace('_',' ',$k)))?> weight</label><input class="weight" data-key="<?=htmlspecialchars($k)?>" type="number" min="0" max="100" step="1" value="<?=htmlspecialchars((string)$v)?>" <?=$pro?'':'disabled title="Pro required to override weights"'?>></div><?php endforeach; ?></div><p><button onclick="generate()">Generate shortlist</button> <button class="secondary" onclick="loadMatrix()">Load saved matrix</button><?php if($pro): ?> <button class="secondary" onclick="exportMatrix()">Export JSON</button><?php endif; ?></p><p class="muted"><?=$pro?'Pro: weight overrides, sensitivity and export enabled.':'Registered: approved default weights are used. Upgrade to Pro for weight overrides, sensitivity and export.'?></p></div><div id="out"></div><div id="msg"></div></main><script>
const csrf=<?=json_encode($csrf)?>,pro=<?=$pro?'true':'false'?>;
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
async function api(url,opt={}){opt.headers={...(opt.headers||{}),'Content-Type':'application/json','X-CSRF-Token':csrf};let r=await fetch(url,opt),d=await r.json().catch(()=>({error:'invalid_response'}));if(!r.ok)throw new Error(d.error||'request_failed');return d}
function weights(){let o={};document.querySelectorAll('.weight').forEach(e=>o[e.dataset.key]=+e.value);return o}
async function generate(){let pid=+document.getElementById('pid').value;if(!pid)return msg('Project ID is required');try{let d=await api(`/api/selection-projects/${pid}/matrix`,{method:'POST',body:JSON.stringify({weights:pro?weights():{},sensitivity:pro})});render(d.matrix.results,d.sensitivity)}catch(e){msg(e.message)}}
async function loadMatrix(){let pid=+document.getElementById('pid').value;if(!pid)return msg('Project ID is required');try{let d=await api(`/api/selection-projects/${pid}/matrix`);let rows=(d.shortlist||[]).map(x=>({product:{id:x.product_id,name:x.product_name,slug:x.product_slug,vendor:x.vendor_name},project_fit_score:x.project_fit_score,baseline_evaluation_score:x.baseline_evaluation_score,mandatory_gap_count:+x.mandatory_gap_count,dimensions:x.score_breakdown?.dimensions||{},contributions:x.score_breakdown?.contributions||{},tradeoffs:x.rationale?.tradeoffs||[],shortlist_state:x.shortlist_state}));render(rows,null)}catch(e){msg(e.message)}}
function render(rows,sensitivity){document.getElementById('out').innerHTML=`<div class="card"><h2>Shortlist</h2><p class="muted">Software ranking is independent from provider discovery. Use the provider link after choosing products you want to investigate.</p>${rows.map((r,i)=>`<div class="product"><div><span class="badge">#${i+1}</span> <strong>${esc(r.product.name)}</strong> ${r.product.vendor?`<span class="muted">· ${esc(r.product.vendor)}</span>`:''}</div><div class="score">${esc(r.project_fit_score)}%</div><div class="muted">Project fit · baseline TechSelectAI evaluation: ${r.baseline_evaluation_score==null?'separate / not available yet':esc(r.baseline_evaluation_score)}</div><div class="${r.mandatory_gap_count?'warning':'ok'}">${r.mandatory_gap_count?`${r.mandatory_gap_count} mandatory gap(s) unresolved`:'No mandatory gaps detected'}</div><div class="dims">${Object.entries(r.dimensions||{}).map(([k,v])=>`<div><strong>${esc(k)}</strong><br>${v==null?'not evaluated':esc(v)+'%'}</div>`).join('')}</div>${(r.tradeoffs||[]).length?`<p><strong>Trade-offs:</strong> ${r.tradeoffs.map(esc).join('; ')}</p>`:''}<p><select onchange="setState(${r.product.id},this.value)"><option value="researching" ${(r.shortlist_state||'researching')==='researching'?'selected':''}>Researching</option><option value="shortlisted" ${r.shortlist_state==='shortlisted'?'selected':''}>Shortlisted</option><option value="rejected" ${r.shortlist_state==='rejected'?'selected':''}>Rejected</option><option value="preferred" ${r.shortlist_state==='preferred'?'selected':''}>Preferred</option></select></p>${r.product.slug?`<a class="provider-link" href="/partners?software=${encodeURIComponent(r.product.slug)}">Find verified vendors / implementation partners</a>`:''}</div>`).join('')}</div>${sensitivity?`<div class="card"><h2>Sensitivity</h2><p class="muted">Top 3 if each criterion weight is increased by 20% independently.</p><pre>${esc(JSON.stringify(sensitivity,null,2))}</pre></div>`:''}`}
async function setState(productId,state){let pid=+document.getElementById('pid').value;try{await api(`/api/selection-projects/${pid}/shortlist/${productId}`,{method:'PUT',body:JSON.stringify({state})});msg('Shortlist state saved',true)}catch(e){msg(e.message)}}
async function exportMatrix(){let pid=+document.getElementById('pid').value;if(!pid)return;try{let d=await api(`/api/selection-projects/${pid}/matrix-export`);let blob=new Blob([JSON.stringify(d,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`techselectai-decision-matrix-${pid}.json`;a.click();URL.revokeObjectURL(a.href)}catch(e){msg(e.message)}}
function msg(t,ok=false){let e=document.getElementById('msg');e.textContent=t;e.style.color=ok?'#166534':'#b91c1c'}if(document.getElementById('pid').value)loadMatrix();
</script></body></html>